def test_do_search_reads_solr_json(monkeypatch):
    response = {
        'response': {'numFound': 1, 'docs': [{'key': 'OL1W'}]},
        'facet_counts': {'facet_fields': {'has_fulltext': ['false', 4, 'true', 1]}},
        'spellcheck': {'suggestions': ['query', {'suggestion': ['queries']}]},
    }
    monkeypatch.setattr(code, 'run_solr_query', lambda *args, **kwargs: (json.dumps(response).encode(), 'url', []))
    result = code.do_search({'q': 'query'}, None)
    assert result.num_found == 1
    assert result.docs == [{'key': 'OL1W'}]
    assert result.facet_counts['has_fulltext'] == [('true', 'yes', 1), ('false', 'no', 4)]
    assert result.spellcheck == {'query': ['queries']}


