def read_author_facet(af):
    # example input: "OL26783A Leo Tolstoy"
    return re_author_facet.match(af).groups()


def get_language_name(code):
    lang = web.ctx.site.get('/languages/' + code)
    return lang.name if lang else "'%s' unknown" % code


def process_facet(facets: str, values: Iterable[tuple[str, int]]):
    if facets == 'has_fulltext':
        counts = dict(values)
        yield ('true', 'yes', counts.get('true', 0))
        yield ('false', 'no', counts.get('false', 0))
        return
    for key, count in values:
        if not count:
            continue
        if facets in ('author_facet', 'author_key'):
            key, display = read_author_facet(key)
        elif facets == 'language':
            display = get_language_name(key)
        else:
            display = key
        yield (key, display, count)


def process_facet_counts(facet_fields: dict[str, list]):
    for name, values in facet_fields.items():
        field = 'author_key' if name == 'author_facet' else name
        pairs = zip(values[::2], values[1::2])
        yield field, list(process_facet(field, pairs))


